// Matches a selected word against the published topic lists of the Bible Dictionary, Guide to the
// Scriptures, and Topical Guide. The lists (titles and official URL slugs only) are generated by
// scripts/generateStudyHelpsIndex.mjs into src/lib/generated/studyHelpsIndex.json.
//
// Kept free of imports so the generator script can load it directly with Node's type stripping.

export type StudyHelpGuideId = "bd" | "gs" | "tg";

/** A topic title whose slug is `slugifyStudyHelpTitle(title)`, or `[title, slug]` when it is not. */
export type StudyHelpIndexEntry = string | [title: string, slug: string];

export type StudyHelpsIndex = {
  source: string;
  retrieved: string;
  guides: Record<StudyHelpGuideId, { tocUrl: string; entries: StudyHelpIndexEntry[] }>;
};

export type StudyHelpGuide = { id: StudyHelpGuideId; label: string; description: string };

export const STUDY_HELP_GUIDES: StudyHelpGuide[] = [
  { id: "bd", label: "Bible Dictionary", description: "Bible people, places, and terms" },
  { id: "gs", label: "Guide to the Scriptures", description: "Topics across all the standard works" },
  { id: "tg", label: "Topical Guide", description: "Verses gathered by topic" },
];

const STUDY_HELP_BASE_URL = "https://www.churchofjesuschrist.org/study/scriptures";

export function studyHelpBrowseUrl(guide: StudyHelpGuideId): string {
  return `${STUDY_HELP_BASE_URL}/${guide}?lang=eng`;
}

export function studyHelpEntryUrl(guide: StudyHelpGuideId, slug: string): string {
  return `${STUDY_HELP_BASE_URL}/${guide}/${encodeURIComponent(slug)}?lang=eng`;
}

function foldText(value: string): string {
  return value
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/[‘’ʼ]/g, "'")
    .toLowerCase();
}

/** The slug the published guides use for most titles; titles that differ are stored with their slug. */
export function slugifyStudyHelpTitle(title: string): string {
  return foldText(title)
    .replace(/'/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

export function normalizePhrase(value: string): string {
  return foldText(value)
    .replace(/'s\b/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

/** The selected word as matched against topic titles: lowercase, unaccented, without a possessive. */
export function normalizeStudyTerm(word: string): string {
  return normalizePhrase(word);
}

// Simple English inflections, so "prophets" also finds "Prophet" and "mercies" finds "Mercy".
export function termForms(term: string): string[] {
  const forms = [term];
  if (term.length > 4 && term.endsWith("ies")) forms.push(`${term.slice(0, -3)}y`);
  if (term.length > 3 && /(?:ses|xes|zes|ches|shes)$/.test(term)) forms.push(term.slice(0, -2));
  if (term.length > 3 && term.endsWith("s") && !term.endsWith("ss")) forms.push(term.slice(0, -1));
  return [...new Set(forms)];
}

// Words too common to find a useful related topic by themselves.
export const RELATED_STOPWORDS = new Set([
  "a", "an", "and", "are", "as", "at", "be", "but", "by", "did", "do", "for", "from", "had", "has", "have", "he",
  "her", "him", "his", "i", "in", "is", "it", "me", "my", "not", "o", "of", "on", "or", "our", "shall", "she",
  "that", "the", "thee", "their", "them", "they", "thou", "thy", "to", "unto", "us", "was", "we", "were", "which",
  "who", "will", "with", "ye", "you", "your",
]);

type PreparedEntry = {
  title: string;
  slug: string;
  /** The whole title as plain words, padded with spaces for whole-word searches. */
  padded: string;
  full: string;
  headword: string;
  /** Other forms a title lists after its headword, such as "Abstinence" in "Abstain, Abstinence". */
  alternatives: string[];
};

function prepareEntry(entry: StudyHelpIndexEntry): PreparedEntry {
  const [title, slug] = typeof entry === "string" ? [entry, slugifyStudyHelpTitle(entry)] : entry;
  // "Bear, Bare, Born, Borne [verb]" and "Mormon(s)" qualify their headings; the qualifier is not a form.
  const plain = title.replace(/\[[^\]]*\]|\([^)]*\)/g, " ");
  const parts = plain
    .split(/,|\s+or\s+/i)
    .map((part) => part.trim().replace(/^or\s+/i, ""))
    .filter(Boolean);
  const [headword = "", ...rest] = parts.map(normalizePhrase);
  // "Calves, golden, worship of" names one topic; "Amalek, Amalekites" lists forms of one word.
  const listsForms = rest.length > 0 && parts.slice(1).every((part) => !/\s/.test(part) && !part.startsWith("-"));
  const full = normalizePhrase(plain);
  return { title, slug, padded: ` ${full} `, full, headword, alternatives: listsForms ? rest : [] };
}

const preparedCache = new WeakMap<StudyHelpIndexEntry[], PreparedEntry[]>();

function prepareEntries(entries: StudyHelpIndexEntry[]): PreparedEntry[] {
  let prepared = preparedCache.get(entries);
  if (!prepared) {
    prepared = entries.map(prepareEntry);
    preparedCache.set(entries, prepared);
  }
  return prepared;
}

export type StudyHelpMatch = { title: string; slug: string };
export type StudyHelpMatches = {
  /** Topics headed by the selected word (or one of its listed forms). */
  entries: StudyHelpMatch[];
  /** Other topics whose titles contain the word. */
  related: StudyHelpMatch[];
};

export const NO_STUDY_HELP_MATCHES: StudyHelpMatches = { entries: [], related: [] };

export function findStudyHelpMatches(
  entries: StudyHelpIndexEntry[],
  word: string,
  { maxEntries = 3, maxRelated = 4 }: { maxEntries?: number; maxRelated?: number } = {}
): StudyHelpMatches {
  const term = normalizeStudyTerm(word);
  if (!term) return NO_STUDY_HELP_MATCHES;
  const forms = termForms(term);
  const searchRelated = term.length > 2 && !RELATED_STOPWORDS.has(term);

  const exact: { match: StudyHelpMatch; rank: number }[] = [];
  const related: { match: StudyHelpMatch; rank: number }[] = [];

  for (const entry of prepareEntries(entries)) {
    const match = { title: entry.title, slug: entry.slug };
    // The word itself outranks an inflected form; a whole-title match outranks a headword or listed form.
    const exactRank = forms.reduce<number>((best, form, formIndex) => {
      const rank =
        entry.full === form ? 0
        : entry.headword === form ? 1
        : entry.alternatives.includes(form) ? 2
        : -1;
      return rank < 0 ? best : Math.min(best, formIndex * 3 + rank);
    }, Number.POSITIVE_INFINITY);
    if (Number.isFinite(exactRank)) {
      exact.push({ match, rank: exactRank });
      continue;
    }
    if (!searchRelated) continue;
    const position = forms.reduce<number>((best, form) => {
      const index = entry.padded.indexOf(` ${form} `);
      return index < 0 ? best : Math.min(best, index);
    }, Number.POSITIVE_INFINITY);
    // Topics that start with the word come first, then shorter (more focused) titles.
    if (Number.isFinite(position)) related.push({ match, rank: (position === 0 ? 0 : 1000) + entry.full.length });
  }

  const byRank = (a: { match: StudyHelpMatch; rank: number }, b: { match: StudyHelpMatch; rank: number }) =>
    a.rank - b.rank || a.match.title.localeCompare(b.match.title);
  return {
    entries: exact.sort(byRank).slice(0, maxEntries).map((item) => item.match),
    related: related.sort(byRank).slice(0, maxRelated).map((item) => item.match),
  };
}
